/* part:page.style.kit.evidence-checklist */
/* Kit css: Evidence checklist    kit version 0.1.0    pairs with kit/evidence-checklist.js
   .kit-ev > p.kit-ev-sum, ol.kit-ev-stages (button.kit-ev-stage), div.kit-ev-body > ul.kit-ev-list (li.kit-ev-grp, button.kit-ev-item[data-status]) + section.kit-ev-pane
   The list and the pane sit side by side and stack below about 38rem (a container query), so it also works in a narrow pane.
   Needs from the board: --bg --panel --sunk --ink --ink-2 --ink-3 --rule --accent --f-ui --f-mono; optional --ok --warn --radius --on-accent */
.kit-ev { container-type: inline-size; display: grid; gap: 12px; min-width: 0; font: 15px/1.45 var(--f-ui); color: var(--ink); }
.kit-ev-sum { margin: 0; font: 600 14px/1.3 var(--f-ui); color: var(--ink-2); }
.kit-ev-stages { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; counter-reset: kit-ev; }
.kit-ev-stages li { flex: 1 1 9rem; min-width: 0; }
.kit-ev-stage { width: 100%; display: grid; gap: 2px; text-align: left; padding: 8px 12px; border: 1px solid var(--rule); border-top: 3px solid var(--warn, var(--accent)); border-radius: var(--radius, 6px); background: var(--panel); color: var(--ink); font: inherit; cursor: pointer; }
.kit-ev-stage.kit-ev-clear { border-top-color: var(--ok, var(--rule)); }
.kit-ev-stage[aria-current] { background: var(--sunk); box-shadow: inset 0 0 0 1px var(--ink-2); }
.kit-ev-sl { font-weight: 600; overflow-wrap: anywhere; } .kit-ev-sn { font: 12.5px/1.3 var(--f-mono); color: var(--ink-2); }
.kit-ev-body { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 14px; align-items: start; }
.kit-ev-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 2px; min-width: 0; }
.kit-ev-grp { margin: 10px 0 2px; font: 600 12.5px/1.3 var(--f-mono); color: var(--ink-2); } .kit-ev-grp:first-child { margin-top: 0; }
.kit-ev-item { width: 100%; display: flex; gap: 10px; align-items: flex-start; text-align: left; padding: 8px 10px; border: 1px solid transparent; border-radius: var(--radius, 6px); background: transparent; color: var(--ink); font: inherit; cursor: pointer; }
.kit-ev-item:hover { background: var(--sunk); }
.kit-ev-item[aria-current="true"] { background: var(--panel); border-color: var(--rule); box-shadow: inset 3px 0 0 var(--accent); }
.kit-ev-it { display: grid; gap: 1px; min-width: 0; } .kit-ev-il { overflow-wrap: anywhere; }
.kit-ev-it small { font-size: 12.5px; color: var(--ink-2); overflow-wrap: anywhere; }
.kit-ev-dot { flex: none; width: 12px; height: 12px; margin-top: 4px; border-radius: 50%; border: 2px solid var(--warn, var(--ink-2)); }
.kit-ev-item[data-status="provided"] .kit-ev-dot { background: var(--ok, var(--ink-2)); border-color: var(--ok, var(--ink-2)); }
.kit-ev-item[data-status="not_needed"] .kit-ev-dot { border-style: dashed; border-color: var(--ink-3, var(--rule)); }
.kit-ev-item[data-status="not_needed"] .kit-ev-il { color: var(--ink-2); }
.kit-ev-pane { display: grid; gap: 10px; padding: 14px 16px; border: 1px solid var(--rule); border-radius: var(--radius, 8px); background: var(--panel); min-width: 0; }
.kit-ev-st { margin: 0; font: 600 12.5px/1.3 var(--f-mono); color: var(--warn, var(--ink-2)); }
.kit-ev-st-provided { color: var(--ok, var(--ink-2)); } .kit-ev-st-not_needed { color: var(--ink-2); }
.kit-ev-h { margin: 0; font: 600 17px/1.3 var(--f-display, var(--f-ui)); overflow-wrap: anywhere; }
.kit-ev-why { margin: 0; color: var(--ink-2); }
.kit-ev-files { margin: 0; padding: 0; list-style: none; display: grid; gap: 4px; }
.kit-ev-files li { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; padding: 6px 10px; border-radius: var(--radius, 6px); background: var(--sunk); min-width: 0; }
.kit-ev-files a, .kit-ev-files span { flex: 1 1 auto; min-width: 0; overflow-wrap: anywhere; color: var(--ink); }
.kit-ev-files small { color: var(--ink-2); }
.kit-ev-drop { display: grid; gap: 8px; justify-items: center; text-align: center; padding: 16px 12px; border: 2px dashed var(--rule); border-radius: var(--radius, 8px); color: var(--ink-2); }
.kit-ev-drop p { margin: 0; } .kit-ev-over { border-color: var(--accent); background: var(--sunk); }
.kit-ev-link { display: grid; gap: 4px; font-size: 13.5px; color: var(--ink-2); }
.kit-ev-link select { font: inherit; color: var(--ink); background: var(--bg); border: 1px solid var(--rule); border-radius: var(--radius, 6px); padding: 6px 8px; max-width: 100%; }
.kit-ev-acts { display: flex; flex-wrap: wrap; gap: 6px; }
.kit-ev-btn { font: 500 13.5px/1.2 var(--f-ui); color: var(--ink); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 6px); padding: 7px 12px; cursor: pointer; }
.kit-ev-btn:hover { background: var(--sunk); }
.kit-ev-pri { color: var(--on-accent, #fff); background: var(--accent); border-color: var(--accent); } .kit-ev-pri:hover { background: var(--accent); filter: brightness(1.08); }
.kit-ev-plain { background: transparent; border-color: transparent; color: var(--ink-2); text-decoration: underline; padding-inline: 4px; }
.kit-ev button:focus-visible, .kit-ev select:focus-visible, .kit-ev a:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
@container (max-width: 38rem) { .kit-ev-body { grid-template-columns: minmax(0, 1fr); } }
/* /part:page.style.kit.evidence-checklist */

/* part:page.script.kit.evidence-checklist */
/**
 * Evidence checklist
 * Kit.evidenceChecklist.mount(box, opts) lists the documents a file must hold, grouped, each with why it is needed and at which stage, and shows how many are still missing per stage. Picking an item opens its pane: what it is for, the files linked to it, a drop zone and a file picker to add one, a list of loose files to link instead, "Take a photo" when kit.camera-capture is loaded, and "Not needed here". The stages are data too, so "Before signing" in one case is "Before applying" in another.
 *
 * What it is: the to-do list of proof behind a decision (a visa, a supplier, a tenancy, a loan, a claim). An item counts as on file when a file is linked to it, as not needed when the page says so, and as missing otherwise.
 * The kit keeps no data: it reports what the person did (onAdd, onLink, onUnlink, onStatus) and the page stores it and calls update() with the new lists. It never uploads anything.
 * API (small and stable):
 *   Kit.evidenceChecklist.mount(box, {stages, requirements, files, selected, label, accept, camera, words, onSelect, onAdd, onLink, onUnlink, onStatus}) -> {update(opts), select(id), destroy()}
 *     stages        [{id, label}]                       in order; "label" reads after "needed", so write "Before applying"
 *     requirements  [{id, group, label, why, stage, status, consent}]   status "missing" (default) | "not_needed"; a linked file makes it "provided"
 *                   consent: the words the camera asks agreement to when the photo is of a person or their document
 *     files         [{id, name, req, url, note}]        req is the requirement id it proves, or empty for a loose file
 *     selected      the requirement id to open first (default: the first missing one)
 *     accept        the file picker's accept (default "image/*,application/pdf"); camera false hides "Take a photo"
 *     words         {missing, provided, not_needed}     the status words (default "Missing", "On file", "Not needed here")
 *     onSelect(req)  onAdd(req, File, capture)  onLink(req, file)  onUnlink(req, file)  onStatus(req, "missing" | "not_needed")
 *                   capture is camera-capture's result (with its consent record) when the file came from "Take a photo"
 *   select(id) opens an item from outside (a link in the page, a search).
 *
 * @id        kit.evidence-checklist
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.0
 * @updated   2026-11-21
 * @summary   The documents a file must hold, grouped, with why and when each is needed and how many are missing per stage; each opens a pane to add, link or photograph the file.
 * @tags      checklist, evidence, documents, requirements, upload, attachments, kyc, onboarding, visa, compliance, due diligence, stages, drop zone
 * @requires  none
 * @files     kit/evidence-checklist.css, kit/samples/evidence-checklist.json, kit/previews/evidence-checklist.js
 * @provides  Kit.evidenceChecklist.mount
 * @config    Kit.evidenceChecklist.mount(box, opts) | stages [{id, label}], requirements [{id, group, label, why, stage, status, consent}], files [{id, name, req, url, note}], selected, accept, camera, words; returns {update(opts), select(id), destroy()}
 * @config    events | onSelect(req), onAdd(req, File, capture), onLink(req, file), onUnlink(req, file), onStatus(req, "missing" | "not_needed"); the kit stores nothing
 * @config    optional | Kit.cameraCapture (kit.camera-capture) adds "Take a photo"
 * @tokens    --bg --panel --sunk --ink --ink-2 --ink-3 --rule --accent --ok? --warn? --f-ui --f-mono --radius?
 * @globals   none
 * @db        none
 * @source    Catalog harvest, 2026-11-21 | an agreement review board | the documents a file needs before and after signing
 * @preview   {"render": "kit.evidence-checklist", "samples": ["kit/samples/evidence-checklist.json"], "uses": ["kit.camera-capture"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; };
const btn = (txt, cls, fn) => { const b = el('button', 'kit-ev-btn' + (cls ? ' ' + cls : ''), txt); b.type = 'button'; b.onclick = fn; return b; };
const WORDS = { missing: 'Missing', provided: 'On file', not_needed: 'Not needed here' };
const lower = s => s ? s.charAt(0).toLowerCase() + s.slice(1) : '';

function mount(box, opts) {
  const o = Object.assign({ stages: [], requirements: [], files: [], selected: null, label: 'Documents', accept: 'image/*,application/pdf', camera: true, words: {} }, opts);
  let sel = o.selected, uid = 0;
  const pre = 'kit-ev-' + Math.random().toString(36).slice(2, 7) + '-';
  box.classList.add('kit-ev');
  const words = () => Object.assign({}, WORDS, o.words);
  const filesOf = r => o.files.filter(f => f.req === r.id);
  const statusOf = r => r.status === 'not_needed' ? 'not_needed' : filesOf(r).length ? 'provided' : 'missing';
  const stageOf = r => o.stages.find(s => s.id === r.stage);
  const missing = () => o.requirements.filter(r => statusOf(r) === 'missing');

  function stagebar() {
    const nav = el('ol', 'kit-ev-stages'); nav.setAttribute('aria-label', 'Stages');
    o.stages.forEach(s => {
      const reqs = o.requirements.filter(r => r.stage === s.id), n = reqs.filter(r => statusOf(r) === 'missing').length;
      const cur = sel && (o.requirements.find(r => r.id === sel) || {}).stage === s.id;
      const li = el('li'); const b = btn('', 'kit-ev-stage' + (n ? '' : ' kit-ev-clear'), () => { const r = reqs.find(x => statusOf(x) === 'missing') || reqs[0]; if (r) pick(r.id, true); });
      if (cur) b.setAttribute('aria-current', 'step');
      b.append(el('span', 'kit-ev-sl', s.label), el('span', 'kit-ev-sn', reqs.length ? (n ? n + ' missing' : 'all in') : 'nothing needed'));
      li.append(b); nav.append(li);
    });
    return nav;
  }
  function list() {
    const ul = el('ul', 'kit-ev-list'); ul.setAttribute('aria-label', o.label);
    const groups = [...new Set(o.requirements.map(r => r.group || ''))];
    groups.forEach(g => {
      if (g) ul.append(el('li', 'kit-ev-grp', g));
      o.requirements.filter(r => (r.group || '') === g).forEach(r => {
        const st = statusOf(r), fs = filesOf(r), li = el('li');
        const b = btn('', 'kit-ev-item', () => pick(r.id, true)); b.dataset.status = st; b.dataset.id = r.id;
        if (r.id === sel) b.setAttribute('aria-current', 'true');
        const txt = el('span', 'kit-ev-it'); txt.append(el('span', 'kit-ev-il', r.label), el('small', null, st === 'provided' ? words().provided + ': ' + fs.map(f => f.name).join(', ') : words()[st]));
        const dot = el('span', 'kit-ev-dot'); dot.setAttribute('aria-hidden', 'true');
        b.append(dot, txt); li.append(b); ul.append(li);
      });
    });
    return ul;
  }
  function pane(r) {
    const p = el('section', 'kit-ev-pane'), st = statusOf(r), stage = stageOf(r), hid = pre + 'h' + (++uid);
    p.setAttribute('aria-labelledby', hid);
    p.append(el('p', 'kit-ev-st kit-ev-st-' + st, words()[st] + (st === 'missing' && stage ? ', needed ' + lower(stage.label) : '')));
    const h = el('h4', 'kit-ev-h', r.label); h.id = hid; p.append(h);
    if (r.why) p.append(el('p', 'kit-ev-why', r.why));
    const fs = filesOf(r);
    if (fs.length) {
      const ul = el('ul', 'kit-ev-files');
      fs.forEach(f => {
        const li = el('li'); const n = f.url ? el('a', null, f.name) : el('span', null, f.name); if (f.url) { n.href = f.url; n.target = '_blank'; n.rel = 'noopener'; }
        li.append(n); if (f.note) li.append(el('small', null, f.note));
        if (o.onUnlink) li.append(btn('Unlink', 'kit-ev-plain', () => o.onUnlink(r, f)));
        ul.append(li);
      });
      p.append(ul);
    }
    if (st !== 'not_needed') {
      if (o.onAdd) {
        const drop = el('div', 'kit-ev-drop'), inp = el('input'); inp.type = 'file'; inp.accept = o.accept; inp.multiple = true; inp.hidden = true;
        inp.onchange = () => { [...inp.files].forEach(f => o.onAdd(r, f)); inp.value = ''; };
        drop.append(el('p', null, fs.length ? 'Drop another file here' : 'Drop the file here'));
        const acts = el('div', 'kit-ev-acts'); acts.append(btn('Choose a file', 'kit-ev-pri', () => inp.click()));
        if (o.camera && Kit.cameraCapture) acts.append(btn('Take a photo', '', async () => {
          const got = await Kit.cameraCapture.open({ title: r.label, hint: r.why, consent: r.consent });
          if (got) o.onAdd(r, new File([got.blob], (r.id || 'photo') + '.jpg', { type: got.blob.type || 'image/jpeg' }), got);
        }));
        drop.append(acts, inp);
        drop.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('kit-ev-over'); });
        drop.addEventListener('dragleave', () => drop.classList.remove('kit-ev-over'));
        drop.addEventListener('drop', e => { e.preventDefault(); drop.classList.remove('kit-ev-over'); [...(e.dataTransfer && e.dataTransfer.files || [])].forEach(f => o.onAdd(r, f)); });
        p.append(drop);
      }
      const loose = o.files.filter(f => !f.req);
      if (o.onLink && loose.length) {
        const row = el('div', 'kit-ev-link'), id = pre + 'l' + uid, lab = el('label', null, 'Or link a file already here'); lab.htmlFor = id;
        const s = el('select'); s.id = id; s.append(el('option', null, 'Choose…')); s.firstChild.value = '';
        loose.forEach(f => { const op = el('option', null, f.name); op.value = f.id; s.append(op); });
        s.onchange = () => { const f = loose.find(x => x.id === s.value); if (f) o.onLink(r, f); };
        row.append(lab, s); p.append(row);
      }
    }
    if (o.onStatus) {
      const acts = el('div', 'kit-ev-acts');
      if (st === 'not_needed') acts.append(btn('Needed after all', '', () => o.onStatus(r, 'missing')));
      else if (st === 'missing') acts.append(btn(words().not_needed, 'kit-ev-plain', () => o.onStatus(r, 'not_needed')));
      if (acts.childNodes.length) p.append(acts);
    }
    return p;
  }
  function draw(focusSel) {
    if (!o.requirements.find(r => r.id === sel)) sel = (missing()[0] || o.requirements[0] || {}).id;
    box.textContent = ''; uid = 0;
    const left = o.requirements.length - missing().length;
    const head = el('p', 'kit-ev-sum'); head.setAttribute('aria-live', 'polite');
    head.textContent = missing().length ? left + ' of ' + o.requirements.length + ' settled, ' + missing().length + ' missing' : 'Everything needed is on file';
    const body = el('div', 'kit-ev-body'), r = o.requirements.find(x => x.id === sel);
    body.append(list()); if (r) body.append(pane(r));
    box.append(head, stagebar(), body);
    if (focusSel) { const b = box.querySelector('.kit-ev-item[aria-current="true"]'); if (b) b.focus(); }
  }
  function pick(id, user) { sel = id; draw(user); if (o.onSelect) o.onSelect(o.requirements.find(r => r.id === id)); }
  draw();
  return {
    update(next) { Object.assign(o, next || {}); if (next && next.selected) sel = next.selected; draw(); },
    select(id) { pick(id, false); },
    destroy() { box.textContent = ''; box.classList.remove('kit-ev'); }
  };
}
Kit.evidenceChecklist = Object.freeze({ mount });
})();
/* /part:page.script.kit.evidence-checklist */

/* part:page.script.preview.kit.evidence-checklist */
/* The catalog's live preview of kit.evidence-checklist. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const clone = v => v === undefined ? undefined : JSON.parse(JSON.stringify(v));
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;
const LOG = 'margin:0;font:13px/1.45 var(--f-ui);color:var(--ink-2);min-width:0;flex:1 1 14rem';

// the kit stores nothing: this preview keeps the files and statuses the way a page would, and logs each event
P['kit.evidence-checklist'] = ({ samples }) => {
  const d = first(samples, 'evidence-checklist');
  const [id, setId] = useState(d.cases[0].id);
  const c = d.cases.find(x => x.id === id);
  const box = useRef(null), ev = useRef(null);
  const [st, setSt] = useState(() => ({ reqs: clone(c.requirements), files: clone(c.files) }));
  const [log, setLog] = useState([]);
  const note = (what, r) => setLog(l => [what + ': ' + r.label, ...l].slice(0, 4));
  const events = {
    onAdd: (r, f, cap) => { setSt(s => ({ ...s, files: [...s.files, { id: 'n' + Date.now() + Math.random(), name: f.name, req: r.id, url: URL.createObjectURL(f), note: cap && cap.consent ? 'photo, consent recorded' : Math.round(f.size / 1024) + ' kB' }] })); note('onAdd', r); },
    onLink: (r, f) => { setSt(s => ({ ...s, files: s.files.map(x => x.id === f.id ? { ...x, req: r.id } : x) })); note('onLink', r); },
    onUnlink: (r, f) => { setSt(s => ({ ...s, files: s.files.map(x => x.id === f.id ? { ...x, req: '' } : x) })); note('onUnlink', r); },
    onStatus: (r, v) => { setSt(s => ({ ...s, reqs: s.reqs.map(x => x.id === r.id ? { ...x, status: v } : x) })); note('onStatus ' + v, r); }
  };
  useEffect(() => { const s = { reqs: clone(c.requirements), files: clone(c.files) }; setSt(s); setLog([]);
    ev.current = K().evidenceChecklist.mount(box.current, { stages: c.stages, requirements: s.reqs, files: s.files, label: c.label, ...events });
    return () => ev.current.destroy(); }, [id]);
  useEffect(() => { if (ev.current) ev.current.update({ requirements: st.reqs, files: st.files }); }, [st]);
  return html`<div class="pv-stack">
    <${Cases} d=${d} value=${id} set=${setId}/>
    <${Sim}>files stay in this tab. ${K().cameraCapture ? '"Take a photo" is there because kit.camera-capture is loaded too.' : ''}<//>
    <div ref=${box}></div>
    <p style=${LOG}>${log.length ? 'Events, newest first: ' + log.join(' · ') : 'Pick an item, add or link a file, or mark it not needed: the page gets an event and calls update().'}</p>
  </div>`;
};
})();
/* /part:page.script.preview.kit.evidence-checklist */

